    CreateGroupRequest.add_member(:path, Smithy::Schema::Shapes::ShapeRef.new(shape: PathType, location_name: 'Path', traits: {"smithy.api#documentation" => "<p> The path to the group. For more information about paths, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/Using_Identifiers.html\">IAM\n                identifiers</a> in the <i>IAM User Guide</i>.</p>\n         <p>This parameter is optional. If it is not included, it defaults to a slash (/).</p>\n         <p>This parameter allows (through its <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a>) a string of characters consisting \n    of either a forward slash (/) by itself or a string that must begin and end with forward slashes.\n    In addition, it can contain any ASCII character from the ! (<code>\\u0021</code>) through the DEL character (<code>\\u007F</code>), including \n    most punctuation characters, digits, and upper and lowercased letters.</p>"}))
    CreateGroupRequest.add_member(:group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: GroupNameType, location_name: 'GroupName', traits: {"smithy.api#documentation" => "<p>The name of the group to create. Do not include the path in this value.</p>\n         <p>IAM user, group, role, and policy names must be unique within the account. Names are\n            not distinguished by case. For example, you cannot create resources named both\n            \"MyResource\" and \"myresource\".</p>", "smithy.api#required" => {}}))
