    CreateInstanceProfileRequest.add_member(:instance_profile_name, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceProfileNameType, location_name: 'InstanceProfileName', traits: {"smithy.api#documentation" => "<p>The name of the instance profile to create.</p>\n         <p>This parameter allows (through its <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a>) a string of characters consisting of upper and lowercase alphanumeric \n    characters with no spaces. You can also include any of the following characters: _+=,.@-</p>", "smithy.api#required" => {}}))
    CreateInstanceProfileRequest.add_member(:path, Smithy::Schema::Shapes::ShapeRef.new(shape: PathType, location_name: 'Path', traits: {"smithy.api#documentation" => "<p> The path to the instance profile. For more information about paths, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/Using_Identifiers.html\">IAM\n                Identifiers</a> in the <i>IAM User Guide</i>.</p>\n         <p>This parameter is optional. If it is not included, it defaults to a slash (/).</p>\n         <p>This parameter allows (through its <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a>) a string of characters consisting \n    of either a forward slash (/) by itself or a string that must begin and end with forward slashes.\n    In addition, it can contain any ASCII character from the ! (<code>\\u0021</code>) through the DEL character (<code>\\u007F</code>), including \n    most punctuation characters, digits, and upper and lowercased letters.</p>"}))
    CreateInstanceProfileRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagListType, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of tags that you want to attach to the newly created IAM instance profile.\n      Each tag consists of a key name and an associated value. For more information about tagging, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/id_tags.html\">Tagging IAM resources</a> in the\n      <i>IAM User Guide</i>.</p>\n         <note>\n            <p>If any one of the tags is invalid or if you exceed the allowed maximum number of tags, then the entire request \n   fails and the resource is not created.</p>\n         </note>"}))
