    CreatePolicyVersionRequest.add_member(:policy_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ArnType, location_name: 'PolicyArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the IAM policy to which you want to add a new\n            version.</p>\n         <p>For more information about ARNs, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws-arns-and-namespaces.html\">Amazon Resource Names (ARNs)</a> in the <i>Amazon Web Services General Reference</i>.</p>", "smithy.api#required" => {}}))
    CreatePolicyVersionRequest.add_member(:policy_document, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyDocumentType, location_name: 'PolicyDocument', traits: {"smithy.api#documentation" => "<p>The JSON policy document that you want to use as the content for this new version of\n            the policy.</p>\n         <p>You must provide policies in JSON format in IAM. However, for CloudFormation\n            templates formatted in YAML, you can provide the policy in JSON or YAML format. CloudFormation always converts a YAML policy to JSON format before submitting it to\n            IAM.</p>\n         <p>The maximum length of the policy document that you can pass in this operation,\n            including whitespace, is listed below. To view the maximum character counts of a managed policy with no whitespaces, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_iam-quotas.html#reference_iam-quotas-entity-length\">IAM and STS character quotas</a>.</p>\n         <p>The <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a> \n    used to validate this parameter is a string of characters consisting of the following:</p>\n         <ul>\n            <li>\n               <p>Any printable ASCII \n    character ranging from the space character (<code>\\u0020</code>) through the end of the ASCII character range</p>\n            </li>\n            <li>\n               <p>The printable characters in the Basic Latin and  Latin-1 Supplement character set \n    (through <code>\\u00FF</code>)</p>\n            </li>\n            <li>\n               <p>The special characters tab (<code>\\u0009</code>), line feed (<code>\\u000A</code>), and \n    carriage return (<code>\\u000D</code>)</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CreatePolicyVersionRequest.add_member(:set_as_default, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'SetAsDefault', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Specifies whether to set this version as the policy's default version.</p>\n         <p>When this parameter is <code>true</code>, the new policy version becomes the operative\n            version. That is, it becomes the version that is in effect for the IAM users, groups,\n            and roles that the policy is attached to.</p>\n         <p>For more information about managed policy versions, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/policies-managed-versions.html\">Versioning for managed\n                policies</a> in the <i>IAM User Guide</i>.</p>"}))
    CreatePolicyVersionRequest.type = Types::CreatePolicyVersionRequest
    CreatePolicyVersionResponse.add_member(:policy_version, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyVersion, location_name: 'PolicyVersion', traits: {"smithy.api#documentation" => "<p>A structure containing details about the new policy version.</p>"}))
    CreatePolicyVersionResponse.type = Types::CreatePolicyVersionResponse
    CreateRoleRequest.add_member(:path, Smithy::Schema::Shapes::ShapeRef.new(shape: PathType, location_name: 'Path', traits: {"smithy.api#documentation" => "<p> The path to the role. For more information about paths, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/Using_Identifiers.html\">IAM\n                Identifiers</a> in the <i>IAM User Guide</i>.</p>\n         <p>This parameter is optional. If it is not included, it defaults to a slash (/).</p>\n         <p>This parameter allows (through its <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a>) a string of characters consisting \n    of either a forward slash (/) by itself or a string that must begin and end with forward slashes.\n    In addition, it can contain any ASCII character from the ! (<code>\\u0021</code>) through the DEL character (<code>\\u007F</code>), including \n    most punctuation characters, digits, and upper and lowercased letters.</p>"}))
    CreateRoleRequest.add_member(:role_name, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleNameType, location_name: 'RoleName', traits: {"smithy.api#documentation" => "<p>The name of the role to create.</p>\n         <p>IAM user, group, role, and policy names must be unique within the account. Names are\n            not distinguished by case. For example, you cannot create resources named both\n            \"MyResource\" and \"myresource\".</p>\n         <p>This parameter allows (through its <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a>) a string of characters consisting of upper and lowercase alphanumeric \n    characters with no spaces. You can also include any of the following characters: _+=,.@-</p>", "smithy.api#required" => {}}))
    CreateRoleRequest.add_member(:assume_role_policy_document, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyDocumentType, location_name: 'AssumeRolePolicyDocument', traits: {"smithy.api#documentation" => "<p>The trust relationship policy document that grants an entity permission to assume the\n            role.</p>\n         <p>In IAM, you must provide a JSON policy that has been converted to a string. However,\n            for CloudFormation templates formatted in YAML, you can provide the policy in JSON or YAML\n            format. CloudFormation always converts a YAML policy to JSON format before submitting it to\n            IAM.</p>\n         <p>The <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a> \n    used to validate this parameter is a string of characters consisting of the following:</p>\n         <ul>\n            <li>\n               <p>Any printable ASCII \n    character ranging from the space character (<code>\\u0020</code>) through the end of the ASCII character range</p>\n            </li>\n            <li>\n               <p>The printable characters in the Basic Latin and  Latin-1 Supplement character set \n    (through <code>\\u00FF</code>)</p>\n            </li>\n            <li>\n               <p>The special characters tab (<code>\\u0009</code>), line feed (<code>\\u000A</code>), and \n    carriage return (<code>\\u000D</code>)</p>\n            </li>\n         </ul>\n         <p> Upon success, the response includes the same trust policy in JSON format.</p>", "smithy.api#required" => {}}))
    CreateRoleRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleDescriptionType, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description of the role.</p>"}))
    CreateRoleRequest.add_member(:max_session_duration, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleMaxSessionDurationType, location_name: 'MaxSessionDuration', traits: {"smithy.api#documentation" => "<p>The maximum session duration (in seconds) that you want to set for the specified role.\n            If you do not specify a value for this setting, the default value of one hour is\n            applied. This setting can have a value from 1 hour to 12 hours.</p>\n         <p>Anyone who assumes the role from the CLI or API can use the\n                <code>DurationSeconds</code> API parameter or the <code>duration-seconds</code>\n            CLI parameter to request a longer session. The <code>MaxSessionDuration</code> setting\n            determines the maximum duration that can be requested using the\n                <code>DurationSeconds</code> parameter. If users don't specify a value for the\n                <code>DurationSeconds</code> parameter, their security credentials are valid for one\n            hour by default. This applies when you use the <code>AssumeRole*</code> API operations\n            or the <code>assume-role*</code> CLI operations but does not apply when you use those\n            operations to create a console URL. For more information, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/id_roles_use.html\">Using IAM\n                roles</a> in the <i>IAM User Guide</i>.</p>"}))
    CreateRoleRequest.add_member(:permissions_boundary, Smithy::Schema::Shapes::ShapeRef.new(shape: ArnType, location_name: 'PermissionsBoundary', traits: {"smithy.api#documentation" => "<p>The ARN of the managed policy that is used to set the permissions boundary for the\n            role.</p>\n         <p>A permissions boundary policy defines the maximum permissions that identity-based\n            policies can grant to an entity, but does not grant permissions. Permissions boundaries\n            do not define the maximum permissions that a resource-based policy can grant to an\n            entity. To learn more, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/access_policies_boundaries.html\">Permissions boundaries\n                for IAM entities</a> in the <i>IAM User Guide</i>.</p>\n         <p>For more information about policy types, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/access_policies.html#access_policy-types\">Policy types\n            </a> in the <i>IAM User Guide</i>.</p>"}))
    CreateRoleRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagListType, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of tags that you want to attach to the new role. Each tag consists of a key name and an associated value.\n      For more information about tagging, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/id_tags.html\">Tagging IAM resources</a> in the\n      <i>IAM User Guide</i>.</p>\n         <note>\n            <p>If any one of the tags is invalid or if you exceed the allowed maximum number of tags, then the entire request \n   fails and the resource is not created.</p>\n         </note>"}))
