    CreateSAMLProviderRequest.add_member(:saml_metadata_document, Smithy::Schema::Shapes::ShapeRef.new(shape: SAMLMetadataDocumentType, location_name: 'SAMLMetadataDocument', traits: {"smithy.api#documentation" => "<p>An XML document generated by an identity provider (IdP) that supports SAML 2.0. The\n            document includes the issuer's name, expiration information, and keys that can be used\n            to validate the SAML authentication response (assertions) that are received from the\n            IdP. You must generate the metadata document using the identity management software that\n            is used as your organization's IdP.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/id_roles_providers_saml.html\">About SAML 2.0-based\n                federation</a> in the <i>IAM User Guide</i>\n         </p>", "smithy.api#required" => {}}))
    CreateSAMLProviderRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: SAMLProviderNameType, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the provider to create.</p>\n         <p>This parameter allows (through its <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a>) a string of characters consisting of upper and lowercase alphanumeric \n    characters with no spaces. You can also include any of the following characters: _+=,.@-</p>", "smithy.api#required" => {}}))
    CreateSAMLProviderRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagListType, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of tags that you want to attach to the new IAM SAML provider.\n      Each tag consists of a key name and an associated value. For more information about tagging, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/id_tags.html\">Tagging IAM resources</a> in the\n      <i>IAM User Guide</i>.</p>\n         <note>\n            <p>If any one of the tags is invalid or if you exceed the allowed maximum number of tags, then the entire request \n   fails and the resource is not created.</p>\n         </note>"}))
    CreateSAMLProviderRequest.add_member(:assertion_encryption_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: AssertionEncryptionModeType, location_name: 'AssertionEncryptionMode', traits: {"smithy.api#documentation" => "<p>Specifies the encryption setting for the SAML provider.</p>"}))
    CreateSAMLProviderRequest.add_member(:add_private_key, Smithy::Schema::Shapes::ShapeRef.new(shape: PrivateKeyType, location_name: 'AddPrivateKey', traits: {"smithy.api#documentation" => "<p>The private key generated from your external identity provider. The private key must\n            be a .pem file that uses AES-GCM or AES-CBC encryption algorithm to decrypt SAML\n            assertions.</p>"}))
    CreateSAMLProviderRequest.type = Types::CreateSAMLProviderRequest
    CreateSAMLProviderResponse.add_member(:saml_provider_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ArnType, location_name: 'SAMLProviderArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the new SAML provider resource in IAM.</p>"}))
    CreateSAMLProviderResponse.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagListType, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of tags that are attached to the new IAM SAML provider. The returned list of tags is sorted by tag key.\n      For more information about tagging, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/id_tags.html\">Tagging IAM resources</a> in the\n      <i>IAM User Guide</i>.</p>"}))
    CreateSAMLProviderResponse.type = Types::CreateSAMLProviderResponse
    CreateServiceLinkedRoleRequest.add_member(:aws_service_name, Smithy::Schema::Shapes::ShapeRef.new(shape: GroupNameType, location_name: 'AWSServiceName', traits: {"smithy.api#documentation" => "<p>The service principal for the Amazon Web Services service to which this role is attached. You use a\n            string similar to a URL but without the http:// in front. For example:\n                <code>elasticbeanstalk.amazonaws.com</code>. </p>\n         <p>Service principals are unique and case-sensitive. To find the exact service principal\n            for your service-linked role, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_aws-services-that-work-with-iam.html\">Amazon Web Services services\n                that work with IAM</a> in the <i>IAM User Guide</i>. Look for\n            the services that have <b>Yes </b>in the <b>Service-Linked Role</b> column. Choose the <b>Yes</b> link to view the service-linked role documentation for that\n            service.</p>", "smithy.api#required" => {}}))
