    CreateServiceLinkedRoleRequest.add_member(:custom_suffix, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomSuffixType, location_name: 'CustomSuffix', traits: {"smithy.api#documentation" => "<p></p>\n         <p>A string that you provide, which is combined with the service-provided prefix to form\n            the complete role name. If you make multiple requests for the same service, then you\n            must supply a different <code>CustomSuffix</code> for each request. Otherwise the\n            request fails with a duplicate role name error. For example, you could add\n                <code>-1</code> or <code>-debug</code> to the suffix.</p>\n         <p>Some services do not support the <code>CustomSuffix</code> parameter. If you provide\n            an optional suffix and the operation fails, try the operation again without the\n            suffix.</p>"}))
    CreateServiceLinkedRoleRequest.type = Types::CreateServiceLinkedRoleRequest
    CreateServiceLinkedRoleResponse.add_member(:role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'Role', traits: {"smithy.api#documentation" => "<p>A <a href=\"https://docs.aws.amazon.com/IAM/latest/APIReference/API_Role.html\">Role</a>\n            object that contains details about the newly created role.</p>"}))
    CreateServiceLinkedRoleResponse.type = Types::CreateServiceLinkedRoleResponse
    CreateServiceSpecificCredentialRequest.add_member(:user_name, Smithy::Schema::Shapes::ShapeRef.new(shape: UserNameType, location_name: 'UserName', traits: {"smithy.api#documentation" => "<p>The name of the IAM user that is to be associated with the credentials. The new\n            service-specific credentials have the same permissions as the associated user except\n            that they can be used only to access the specified service.</p>\n         <p>This parameter allows (through its <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a>) a string of characters consisting of upper and lowercase alphanumeric \n    characters with no spaces. You can also include any of the following characters: _+=,.@-</p>", "smithy.api#required" => {}}))
    CreateServiceSpecificCredentialRequest.add_member(:service_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceName, location_name: 'ServiceName', traits: {"smithy.api#documentation" => "<p>The name of the Amazon Web Services service that is to be associated with the credentials. The\n            service you specify here is the only service that can be accessed using these\n            credentials.</p>", "smithy.api#required" => {}}))
    CreateServiceSpecificCredentialRequest.add_member(:credential_age_days, Smithy::Schema::Shapes::ShapeRef.new(shape: CredentialAgeDays, location_name: 'CredentialAgeDays', traits: {"smithy.api#documentation" => "<p>The number of days until the service specific credential expires. This field is only\n            valid for Bedrock API keys and must be a positive integer. When not specified, the\n            credential will not expire.</p>"}))
    CreateServiceSpecificCredentialRequest.type = Types::CreateServiceSpecificCredentialRequest
    CreateServiceSpecificCredentialResponse.add_member(:service_specific_credential, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceSpecificCredential, location_name: 'ServiceSpecificCredential', traits: {"smithy.api#documentation" => "<p>A structure that contains information about the newly created service-specific\n            credential.</p>\n         <important>\n            <p>This is the only time that the password for this credential set is available. It\n                cannot be recovered later. Instead, you must reset the password with <a href=\"https://docs.aws.amazon.com/IAM/latest/APIReference/API_ResetServiceSpecificCredential.html\">ResetServiceSpecificCredential</a>.</p>\n         </important>"}))
