    ServiceSpecificCredentialMetadata.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: StatusType, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the service-specific credential. <code>Active</code> means that the key is\n         valid for API calls, while <code>Inactive</code> means it is not.</p>", "smithy.api#required" => {}}))
    ServiceSpecificCredentialMetadata.add_member(:service_user_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceUserName, location_name: 'ServiceUserName', traits: {"smithy.api#addedDefault" => {}, "smithy.api#default" => "", "smithy.api#documentation" => "<p>The generated user name for the service-specific credential.</p>"}))
    ServiceSpecificCredentialMetadata.add_member(:service_credential_alias, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceCredentialAlias, location_name: 'ServiceCredentialAlias', traits: {"smithy.api#documentation" => "<p>For Bedrock API keys, this is the public portion of the credential that includes the IAM\n         user name and a suffix containing version and creation information.</p>"}))
    ServiceSpecificCredentialMetadata.add_member(:create_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'CreateDate', traits: {"smithy.api#documentation" => "<p>The date and time, in <a href=\"http://www.iso.org/iso/iso8601\">ISO 8601 date-time\n            format</a>, when the service-specific credential were created.</p>", "smithy.api#required" => {}}))
    ServiceSpecificCredentialMetadata.add_member(:expiration_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'ExpirationDate', traits: {"smithy.api#documentation" => "<p>The date and time when the service specific credential expires. This field is only\n         present for Bedrock API keys that were created with an expiration period.</p>"}))
    ServiceSpecificCredentialMetadata.add_member(:service_specific_credential_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceSpecificCredentialId, location_name: 'ServiceSpecificCredentialId', traits: {"smithy.api#documentation" => "<p>The unique identifier for the service-specific credential.</p>", "smithy.api#required" => {}}))
    ServiceSpecificCredentialMetadata.add_member(:service_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceName, location_name: 'ServiceName', traits: {"smithy.api#documentation" => "<p>The name of the service associated with the service-specific credential.</p>", "smithy.api#required" => {}}))
