    SetDefaultPolicyVersionRequest.add_member(:policy_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ArnType, location_name: 'PolicyArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the IAM policy whose default version you want to\n            set.</p>\n         <p>For more information about ARNs, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws-arns-and-namespaces.html\">Amazon Resource Names (ARNs)</a> in the <i>Amazon Web Services General Reference</i>.</p>", "smithy.api#required" => {}}))
    SetDefaultPolicyVersionRequest.add_member(:version_id, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyVersionIdType, location_name: 'VersionId', traits: {"smithy.api#documentation" => "<p>The version of the policy to set as the default (operative) version.</p>\n         <p>For more information about managed policy versions, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/policies-managed-versions.html\">Versioning for managed\n                policies</a> in the <i>IAM User Guide</i>.</p>", "smithy.api#required" => {}}))
    SetDefaultPolicyVersionRequest.type = Types::SetDefaultPolicyVersionRequest
    SetSecurityTokenServicePreferencesRequest.add_member(:global_endpoint_token_version, Smithy::Schema::Shapes::ShapeRef.new(shape: GlobalEndpointTokenVersion, location_name: 'GlobalEndpointTokenVersion', traits: {"smithy.api#documentation" => "<p>The version of the global endpoint token. Version 1 tokens are valid only in Amazon Web Services Regions that are available by default. These tokens do not work in\n            manually enabled Regions, such as Asia Pacific (Hong Kong). Version 2 tokens are valid\n            in all Regions. However, version 2 tokens are longer and might affect systems where you\n            temporarily store tokens.</p>\n         <p>For information, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/id_credentials_temp_enable-regions.html\">Activating and\n                deactivating STS in an Amazon Web Services Region</a> in the\n                <i>IAM User Guide</i>.</p>", "smithy.api#required" => {}}))
    SetSecurityTokenServicePreferencesRequest.type = Types::SetSecurityTokenServicePreferencesRequest
    SigningCertificate.add_member(:user_name, Smithy::Schema::Shapes::ShapeRef.new(shape: UserNameType, location_name: 'UserName', traits: {"smithy.api#documentation" => "<p>The name of the user the signing certificate is associated with.</p>", "smithy.api#required" => {}}))
    SigningCertificate.add_member(:certificate_id, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateIdType, location_name: 'CertificateId', traits: {"smithy.api#documentation" => "<p>The ID for the signing certificate.</p>", "smithy.api#required" => {}}))
    SigningCertificate.add_member(:certificate_body, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateBodyType, location_name: 'CertificateBody', traits: {"smithy.api#documentation" => "<p>The contents of the signing certificate.</p>", "smithy.api#required" => {}}))
    SigningCertificate.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: StatusType, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the signing certificate. <code>Active</code> means that the key is valid\n         for API calls, while <code>Inactive</code> means it is not.</p>", "smithy.api#required" => {}}))
    SigningCertificate.add_member(:upload_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'UploadDate', traits: {"smithy.api#documentation" => "<p>The date when the signing certificate was uploaded.</p>"}))
    SigningCertificate.type = Types::SigningCertificate
    SimulateCustomPolicyOutput.add_member(:evaluation_results, Smithy::Schema::Shapes::ShapeRef.new(shape: EvaluationResultsListType, location_name: 'EvaluationResults', traits: {"smithy.api#documentation" => "<p>The results of the simulation.</p>"}))
    SimulateCustomPolicyOutput.add_member(:is_truncated, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'IsTruncated', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>A flag that indicates whether there are more items to return. If your \n    results were truncated, you can make a subsequent pagination request using the <code>Marker</code>\n    request parameter to retrieve more items. Note that IAM might return fewer than the \n    <code>MaxItems</code> number of results even when there are more results available. We recommend \n    that you check <code>IsTruncated</code> after every call to ensure that you receive all your \n    results.</p>"}))
    SimulateCustomPolicyOutput.add_member(:marker, Smithy::Schema::Shapes::ShapeRef.new(shape: ResponseMarkerType, location_name: 'Marker', traits: {"smithy.api#documentation" => "<p>When <code>IsTruncated</code> is <code>true</code>, this element\n    is present and contains the value to use for the <code>Marker</code> parameter in a subsequent \n    pagination request.</p>"}))
    SimulateCustomPolicyOutput.type = Types::SimulateCustomPolicyOutput
    SimulateCustomPolicyRequest.add_member(:policy_input_list, Smithy::Schema::Shapes::ShapeRef.new(shape: SimulationPolicyListType, location_name: 'PolicyInputList', traits: {"smithy.api#documentation" => "<p>A list of policy documents to include in the simulation. Each document is specified as\n            a string containing the complete, valid JSON text of an IAM policy. Do not include any\n            resource-based policies in this parameter. Any resource-based policy must be submitted\n            with the <code>ResourcePolicy</code> parameter. The policies cannot be \"scope-down\"\n            policies, such as you could include in a call to <a href=\"https://docs.aws.amazon.com/IAM/latest/APIReference/API_GetFederationToken.html\">GetFederationToken</a> or one of\n            the <a href=\"https://docs.aws.amazon.com/IAM/latest/APIReference/API_AssumeRole.html\">AssumeRole</a> API operations. In other words, do not use policies designed to\n            restrict what a user can do while using the temporary credentials.</p>\n         <p>The maximum length of the policy document that you can pass in this operation,\n            including whitespace, is listed below. To view the maximum character counts of a managed policy with no whitespaces, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_iam-quotas.html#reference_iam-quotas-entity-length\">IAM and STS character quotas</a>.</p>\n         <p>The <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a> \n    used to validate this parameter is a string of characters consisting of the following:</p>\n         <ul>\n            <li>\n               <p>Any printable ASCII \n    character ranging from the space character (<code>\\u0020</code>) through the end of the ASCII character range</p>\n            </li>\n            <li>\n               <p>The printable characters in the Basic Latin and  Latin-1 Supplement character set \n    (through <code>\\u00FF</code>)</p>\n            </li>\n            <li>\n               <p>The special characters tab (<code>\\u0009</code>), line feed (<code>\\u000A</code>), and \n    carriage return (<code>\\u000D</code>)</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    SimulateCustomPolicyRequest.add_member(:permissions_boundary_policy_input_list, Smithy::Schema::Shapes::ShapeRef.new(shape: SimulationPolicyListType, location_name: 'PermissionsBoundaryPolicyInputList', traits: {"smithy.api#documentation" => "<p>The IAM permissions boundary policy to simulate. The permissions boundary sets the\n            maximum permissions that an IAM entity can have. You can input only one permissions\n            boundary when you pass a policy to this operation. For more information about\n            permissions boundaries, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/access_policies_boundaries.html\">Permissions boundaries for IAM\n                entities</a> in the <i>IAM User Guide</i>. The policy input is\n            specified as a string that contains the complete, valid JSON text of a permissions\n            boundary policy.</p>\n         <p>The maximum length of the policy document that you can pass in this operation,\n            including whitespace, is listed below. To view the maximum character counts of a managed policy with no whitespaces, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_iam-quotas.html#reference_iam-quotas-entity-length\">IAM and STS character quotas</a>.</p>\n         <p>The <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a> \n    used to validate this parameter is a string of characters consisting of the following:</p>\n         <ul>\n            <li>\n               <p>Any printable ASCII \n    character ranging from the space character (<code>\\u0020</code>) through the end of the ASCII character range</p>\n            </li>\n            <li>\n               <p>The printable characters in the Basic Latin and  Latin-1 Supplement character set \n    (through <code>\\u00FF</code>)</p>\n            </li>\n            <li>\n               <p>The special characters tab (<code>\\u0009</code>), line feed (<code>\\u000A</code>), and \n    carriage return (<code>\\u000D</code>)</p>\n            </li>\n         </ul>"}))
    SimulateCustomPolicyRequest.add_member(:action_names, Smithy::Schema::Shapes::ShapeRef.new(shape: ActionNameListType, location_name: 'ActionNames', traits: {"smithy.api#documentation" => "<p>A list of names of API operations to evaluate in the simulation. Each operation is\n            evaluated against each resource. Each operation must include the service identifier,\n            such as <code>iam:CreateUser</code>. This operation does not support using wildcards (*)\n            in an action name.</p>", "smithy.api#required" => {}}))
    SimulateCustomPolicyRequest.add_member(:resource_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceNameListType, location_name: 'ResourceArns', traits: {"smithy.api#documentation" => "<p>A list of ARNs of Amazon Web Services resources to include in the simulation. If this parameter is\n            not provided, then the value defaults to <code>*</code> (all resources). Each API in the\n                <code>ActionNames</code> parameter is evaluated for each resource in this list. The\n            simulation determines the access result (allowed or denied) of each combination and\n            reports it in the response. You can simulate resources that don't exist in your\n            account.</p>\n         <p>The simulation does not automatically retrieve policies for the specified resources.\n            If you want to include a resource policy in the simulation, then you must include the\n            policy as a string in the <code>ResourcePolicy</code> parameter.</p>\n         <p>If you include a <code>ResourcePolicy</code>, then it must be applicable to all of the\n            resources included in the simulation or you receive an invalid input error.</p>\n         <p>For more information about ARNs, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws-arns-and-namespaces.html\">Amazon Resource Names (ARNs)</a> in the <i>Amazon Web Services General Reference</i>.</p>\n         <note>\n            <p>Simulation of resource-based policies isn't supported for IAM roles.</p>\n         </note>"}))
    SimulateCustomPolicyRequest.add_member(:resource_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyDocumentType, location_name: 'ResourcePolicy', traits: {"smithy.api#documentation" => "<p>A resource-based policy to include in the simulation provided as a string. Each\n            resource in the simulation is treated as if it had this policy attached. You can include\n            only one resource-based policy in a simulation.</p>\n         <p>The maximum length of the policy document that you can pass in this operation,\n            including whitespace, is listed below. To view the maximum character counts of a managed policy with no whitespaces, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_iam-quotas.html#reference_iam-quotas-entity-length\">IAM and STS character quotas</a>.</p>\n         <p>The <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a> \n    used to validate this parameter is a string of characters consisting of the following:</p>\n         <ul>\n            <li>\n               <p>Any printable ASCII \n    character ranging from the space character (<code>\\u0020</code>) through the end of the ASCII character range</p>\n            </li>\n            <li>\n               <p>The printable characters in the Basic Latin and  Latin-1 Supplement character set \n    (through <code>\\u00FF</code>)</p>\n            </li>\n            <li>\n               <p>The special characters tab (<code>\\u0009</code>), line feed (<code>\\u000A</code>), and \n    carriage return (<code>\\u000D</code>)</p>\n            </li>\n         </ul>\n         <note>\n            <p>Simulation of resource-based policies isn't supported for IAM roles.</p>\n         </note>"}))
    SimulateCustomPolicyRequest.add_member(:resource_owner, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceNameType, location_name: 'ResourceOwner', traits: {"smithy.api#documentation" => "<p>An ARN representing the Amazon Web Services account ID that specifies the owner of any simulated\n            resource that does not identify its owner in the resource ARN. Examples of resource ARNs\n            include an S3 bucket or object. If <code>ResourceOwner</code> is specified, it is also\n            used as the account owner of any <code>ResourcePolicy</code> included in the simulation.\n            If the <code>ResourceOwner</code> parameter is not specified, then the owner of the\n            resources and the resource policy defaults to the account of the identity provided in\n                <code>CallerArn</code>. This parameter is required only if you specify a\n            resource-based policy and account that owns the resource is different from the account\n            that owns the simulated calling user <code>CallerArn</code>.</p>\n         <p>The ARN for an account uses the following syntax:\n                    <code>arn:aws:iam::<i>AWS-account-ID</i>:root</code>. For example,\n            to represent the account with the 112233445566 ID, use the following ARN:\n                <code>arn:aws:iam::112233445566-ID:root</code>. </p>"}))
    SimulateCustomPolicyRequest.add_member(:caller_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceNameType, location_name: 'CallerArn', traits: {"smithy.api#documentation" => "<p>The ARN of the IAM user that you want to use as the simulated caller of the API\n            operations. <code>CallerArn</code> is required if you include a\n                <code>ResourcePolicy</code> so that the policy's <code>Principal</code> element has\n            a value to use in evaluating the policy.</p>\n         <p>You can specify only the ARN of an IAM user. You cannot specify the ARN of an\n            assumed role, federated user, or a service principal.</p>"}))
    SimulateCustomPolicyRequest.add_member(:context_entries, Smithy::Schema::Shapes::ShapeRef.new(shape: ContextEntryListType, location_name: 'ContextEntries', traits: {"smithy.api#documentation" => "<p>A list of context keys and corresponding values for the simulation to use. Whenever a\n            context key is evaluated in one of the simulated IAM permissions policies, the\n            corresponding value is supplied.</p>"}))
    SimulateCustomPolicyRequest.add_member(:resource_handling_option, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceHandlingOptionType, location_name: 'ResourceHandlingOption', traits: {"smithy.api#documentation" => "<p>Specifies the type of simulation to run. Different API operations that support\n            resource-based policies require different combinations of resources. By specifying the\n            type of simulation to run, you enable the policy simulator to enforce the presence of\n            the required resources to ensure reliable simulation results. If your simulation does\n            not match one of the following scenarios, then you can omit this parameter. The\n            following list shows each of the supported scenario values and the resources that you\n            must define to run the simulation.</p>\n         <p>Each of the Amazon EC2 scenarios requires that you specify instance, image, and security\n            group resources. If your scenario includes an EBS volume, then you must specify that\n            volume as a resource. If the Amazon EC2 scenario includes VPC, then you must supply the\n            network interface resource. If it includes an IP subnet, then you must specify the\n            subnet resource. For more information on the Amazon EC2 scenario options, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-supported-platforms.html\">Supported platforms</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         <ul>\n            <li>\n               <p>\n                  <b>EC2-VPC-InstanceStore</b>\n               </p>\n               <p>instance, image, security group, network interface</p>\n            </li>\n            <li>\n               <p>\n                  <b>EC2-VPC-InstanceStore-Subnet</b>\n               </p>\n               <p>instance, image, security group, network interface, subnet</p>\n            </li>\n            <li>\n               <p>\n                  <b>EC2-VPC-EBS</b>\n               </p>\n               <p>instance, image, security group, network interface, volume</p>\n            </li>\n            <li>\n               <p>\n                  <b>EC2-VPC-EBS-Subnet</b>\n               </p>\n               <p>instance, image, security group, network interface, subnet, volume</p>\n            </li>\n         </ul>"}))
    SimulateCustomPolicyRequest.add_member(:max_items, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxItemsType, location_name: 'MaxItems', traits: {"smithy.api#documentation" => "<p>Use this only when paginating results to indicate the \n    maximum number of items you want in the response. If additional items exist beyond the maximum \n    you specify, the <code>IsTruncated</code> response element is <code>true</code>.</p>\n         <p>If you do not include this parameter, the number of items defaults to 100. Note that\n    IAM might return fewer results, even when there are more results available. In that case, the\n    <code>IsTruncated</code> response element returns <code>true</code>, and <code>Marker</code> \n    contains a value to include in the subsequent call that tells the service where to continue \n    from.</p>"}))
    SimulateCustomPolicyRequest.add_member(:marker, Smithy::Schema::Shapes::ShapeRef.new(shape: MarkerType, location_name: 'Marker', traits: {"smithy.api#documentation" => "<p>Use this parameter only when paginating results and only after \n    you receive a response indicating that the results are truncated. Set it to the value of the\n    <code>Marker</code> element in the response that you received to indicate where the next call \n    should start.</p>"}))
