    UpdateAccessKeyRequest.add_member(:user_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ExistingUserNameType, location_name: 'UserName', traits: {"smithy.api#documentation" => "<p>The name of the user whose key you want to update.</p>\n         <p>This parameter allows (through its <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a>) a string of characters consisting of upper and lowercase alphanumeric \n    characters with no spaces. You can also include any of the following characters: _+=,.@-</p>"}))
