    UpdateAccessKeyRequest.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: StatusType, location_name: 'Status', traits: {"smithy.api#documentation" => "<p> The status you want to assign to the secret access key. <code>Active</code> means\n            that the key can be used for programmatic calls to Amazon Web Services, while <code>Inactive</code>\n            means that the key cannot be used.</p>", "smithy.api#required" => {}}))
