    UpdateAccountPasswordPolicyRequest.add_member(:minimum_password_length, Smithy::Schema::Shapes::ShapeRef.new(shape: MinimumPasswordLengthType, location_name: 'MinimumPasswordLength', traits: {"smithy.api#documentation" => "<p>The minimum number of characters allowed in an IAM user password.</p>\n         <p>If you do not specify a value for this parameter, then the operation uses the default\n            value of <code>6</code>.</p>"}))
    UpdateAccountPasswordPolicyRequest.add_member(:require_symbols, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'RequireSymbols', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Specifies whether IAM user passwords must contain at least one of the following\n            non-alphanumeric characters:</p>\n         <p>! @ # $ % ^ & * ( ) _ + - = [ ] { } | '</p>\n         <p>If you do not specify a value for this parameter, then the operation uses the default\n            value of <code>false</code>. The result is that passwords do not require at least one\n            symbol character.</p>"}))
    UpdateAccountPasswordPolicyRequest.add_member(:require_numbers, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'RequireNumbers', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Specifies whether IAM user passwords must contain at least one numeric character (0\n            to 9).</p>\n         <p>If you do not specify a value for this parameter, then the operation uses the default\n            value of <code>false</code>. The result is that passwords do not require at least one\n            numeric character.</p>"}))
    UpdateAccountPasswordPolicyRequest.add_member(:require_uppercase_characters, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'RequireUppercaseCharacters', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Specifies whether IAM user passwords must contain at least one uppercase character\n            from the ISO basic Latin alphabet (A to Z).</p>\n         <p>If you do not specify a value for this parameter, then the operation uses the default\n            value of <code>false</code>. The result is that passwords do not require at least one\n            uppercase character.</p>"}))
    UpdateAccountPasswordPolicyRequest.add_member(:require_lowercase_characters, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'RequireLowercaseCharacters', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Specifies whether IAM user passwords must contain at least one lowercase character\n            from the ISO basic Latin alphabet (a to z).</p>\n         <p>If you do not specify a value for this parameter, then the operation uses the default\n            value of <code>false</code>. The result is that passwords do not require at least one\n            lowercase character.</p>"}))
    UpdateAccountPasswordPolicyRequest.add_member(:allow_users_to_change_password, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'AllowUsersToChangePassword', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p> Allows all IAM users in your account to use the Amazon Web Services Management Console to change their own\n            passwords. For more information, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/id_credentials_passwords_enable-user-change.html\">Permitting\n                IAM users to change their own passwords</a> in the\n                <i>IAM User Guide</i>.</p>\n         <p>If you do not specify a value for this parameter, then the operation uses the default\n            value of <code>false</code>. The result is that IAM users in the account do not\n            automatically have permissions to change their own password.</p>"}))
    UpdateAccountPasswordPolicyRequest.add_member(:max_password_age, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxPasswordAgeType, location_name: 'MaxPasswordAge', traits: {"smithy.api#documentation" => "<p>The number of days that an IAM user password is valid.</p>\n         <p>If you do not specify a value for this parameter, then the operation uses the default\n            value of <code>0</code>. The result is that IAM user passwords never expire.</p>"}))
    UpdateAccountPasswordPolicyRequest.add_member(:password_reuse_prevention, Smithy::Schema::Shapes::ShapeRef.new(shape: PasswordReusePreventionType, location_name: 'PasswordReusePrevention', traits: {"smithy.api#documentation" => "<p>Specifies the number of previous passwords that IAM users are prevented from\n            reusing.</p>\n         <p>If you do not specify a value for this parameter, then the operation uses the default\n            value of <code>0</code>. The result is that IAM users are not prevented from reusing\n            previous passwords.</p>"}))
    UpdateAccountPasswordPolicyRequest.add_member(:hard_expiry, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanObjectType, location_name: 'HardExpiry', traits: {"smithy.api#documentation" => "<p> Prevents IAM users who are accessing the account via the Amazon Web Services Management Console from setting a\n            new console password after their password has expired. The IAM user cannot access the\n            console until an administrator resets the password.</p>\n         <p>If you do not specify a value for this parameter, then the operation uses the default\n            value of <code>false</code>. The result is that IAM users can change their passwords\n            after they expire and continue to sign in as the user.</p>\n         <note>\n            <p> In the Amazon Web Services Management Console, the custom password policy option <b>Allow\n                    users to change their own password</b> gives IAM users permissions to\n                    <code>iam:ChangePassword</code> for only their user and to the\n                    <code>iam:GetAccountPasswordPolicy</code> action. This option does not attach a\n                permissions policy to each user, rather the permissions are applied at the\n                account-level for all users by IAM. IAM users with\n                    <code>iam:ChangePassword</code> permission and active access keys can reset\n                their own expired console password using the CLI or API.</p>\n         </note>"}))
    UpdateAccountPasswordPolicyRequest.type = Types::UpdateAccountPasswordPolicyRequest
    UpdateAssumeRolePolicyRequest.add_member(:role_name, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleNameType, location_name: 'RoleName', traits: {"smithy.api#documentation" => "<p>The name of the role to update with the new policy.</p>\n         <p>This parameter allows (through its <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a>) a string of characters consisting of upper and lowercase alphanumeric \n    characters with no spaces. You can also include any of the following characters: _+=,.@-</p>", "smithy.api#required" => {}}))
    UpdateAssumeRolePolicyRequest.add_member(:policy_document, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyDocumentType, location_name: 'PolicyDocument', traits: {"smithy.api#documentation" => "<p>The policy that grants an entity permission to assume the role.</p>\n         <p>You must provide policies in JSON format in IAM. However, for CloudFormation\n            templates formatted in YAML, you can provide the policy in JSON or YAML format. CloudFormation always converts a YAML policy to JSON format before submitting it to\n            IAM.</p>\n         <p>The <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a> \n    used to validate this parameter is a string of characters consisting of the following:</p>\n         <ul>\n            <li>\n               <p>Any printable ASCII \n    character ranging from the space character (<code>\\u0020</code>) through the end of the ASCII character range</p>\n            </li>\n            <li>\n               <p>The printable characters in the Basic Latin and  Latin-1 Supplement character set \n    (through <code>\\u00FF</code>)</p>\n            </li>\n            <li>\n               <p>The special characters tab (<code>\\u0009</code>), line feed (<code>\\u000A</code>), and \n    carriage return (<code>\\u000D</code>)</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    UpdateAssumeRolePolicyRequest.type = Types::UpdateAssumeRolePolicyRequest
    UpdateGroupRequest.add_member(:group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: GroupNameType, location_name: 'GroupName', traits: {"smithy.api#documentation" => "<p>Name of the IAM group to update. If you're changing the name of the group, this is\n            the original name.</p>\n         <p>This parameter allows (through its <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a>) a string of characters consisting of upper and lowercase alphanumeric \n    characters with no spaces. You can also include any of the following characters: _+=,.@-</p>", "smithy.api#required" => {}}))
    UpdateGroupRequest.add_member(:new_path, Smithy::Schema::Shapes::ShapeRef.new(shape: PathType, location_name: 'NewPath', traits: {"smithy.api#documentation" => "<p>New path for the IAM group. Only include this if changing the group's path.</p>\n         <p>This parameter allows (through its <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a>) a string of characters consisting \n    of either a forward slash (/) by itself or a string that must begin and end with forward slashes.\n    In addition, it can contain any ASCII character from the ! (<code>\\u0021</code>) through the DEL character (<code>\\u007F</code>), including \n    most punctuation characters, digits, and upper and lowercased letters.</p>"}))
    UpdateGroupRequest.add_member(:new_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: GroupNameType, location_name: 'NewGroupName', traits: {"smithy.api#documentation" => "<p>New name for the IAM group. Only include this if changing the group's name.</p>\n         <p>IAM user, group, role, and policy names must be unique within the account. Names are\n            not distinguished by case. For example, you cannot create resources named both\n            \"MyResource\" and \"myresource\".</p>"}))
    UpdateGroupRequest.type = Types::UpdateGroupRequest
    UpdateLoginProfileRequest.add_member(:user_name, Smithy::Schema::Shapes::ShapeRef.new(shape: UserNameType, location_name: 'UserName', traits: {"smithy.api#documentation" => "<p>The name of the user whose password you want to update.</p>\n         <p>This parameter allows (through its <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a>) a string of characters consisting of upper and lowercase alphanumeric \n    characters with no spaces. You can also include any of the following characters: _+=,.@-</p>", "smithy.api#required" => {}}))
    UpdateLoginProfileRequest.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: PasswordType, location_name: 'Password', traits: {"smithy.api#documentation" => "<p>The new password for the specified IAM user.</p>\n         <p>The <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a> \n    used to validate this parameter is a string of characters consisting of the following:</p>\n         <ul>\n            <li>\n               <p>Any printable ASCII \n    character ranging from the space character (<code>\\u0020</code>) through the end of the ASCII character range</p>\n            </li>\n            <li>\n               <p>The printable characters in the Basic Latin and  Latin-1 Supplement character set \n    (through <code>\\u00FF</code>)</p>\n            </li>\n            <li>\n               <p>The special characters tab (<code>\\u0009</code>), line feed (<code>\\u000A</code>), and \n    carriage return (<code>\\u000D</code>)</p>\n            </li>\n         </ul>\n         <p>However, the format can be further restricted by the account administrator by setting\n            a password policy on the Amazon Web Services account. For more information, see <a href=\"https://docs.aws.amazon.com/IAM/latest/APIReference/API_UpdateAccountPasswordPolicy.html\">UpdateAccountPasswordPolicy</a>.</p>"}))
    UpdateLoginProfileRequest.add_member(:password_reset_required, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanObjectType, location_name: 'PasswordResetRequired', traits: {"smithy.api#documentation" => "<p>Allows this new password to be used only once by requiring the specified IAM user to\n            set a new password on next sign-in.</p>"}))
    UpdateLoginProfileRequest.type = Types::UpdateLoginProfileRequest
    UpdateOpenIDConnectProviderThumbprintRequest.add_member(:open_id_connect_provider_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ArnType, location_name: 'OpenIDConnectProviderArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the IAM OIDC provider resource object for which\n            you want to update the thumbprint. You can get a list of OIDC provider ARNs by using the\n                <a href=\"https://docs.aws.amazon.com/IAM/latest/APIReference/API_ListOpenIDConnectProviders.html\">ListOpenIDConnectProviders</a> operation.</p>\n         <p>For more information about ARNs, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws-arns-and-namespaces.html\">Amazon Resource Names (ARNs)</a> in the <i>Amazon Web Services General Reference</i>.</p>", "smithy.api#required" => {}}))
    UpdateOpenIDConnectProviderThumbprintRequest.add_member(:thumbprint_list, Smithy::Schema::Shapes::ShapeRef.new(shape: ThumbprintListType, location_name: 'ThumbprintList', traits: {"smithy.api#documentation" => "<p>A list of certificate thumbprints that are associated with the specified IAM OpenID\n            Connect provider. For more information, see <a href=\"https://docs.aws.amazon.com/IAM/latest/APIReference/API_CreateOpenIDConnectProvider.html\">CreateOpenIDConnectProvider</a>. </p>", "smithy.api#required" => {}}))
    UpdateOpenIDConnectProviderThumbprintRequest.type = Types::UpdateOpenIDConnectProviderThumbprintRequest
