    UpdateRoleDescriptionRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleDescriptionType, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>The new description that you want to apply to the specified role.</p>", "smithy.api#required" => {}}))
