    UploadServerCertificateRequest.add_member(:path, Smithy::Schema::Shapes::ShapeRef.new(shape: PathType, location_name: 'Path', traits: {"smithy.api#documentation" => "<p>The path for the server certificate. For more information about paths, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/Using_Identifiers.html\">IAM\n                identifiers</a> in the <i>IAM User Guide</i>.</p>\n         <p>This parameter is optional. If it is not included, it defaults to a slash (/).\n            This parameter allows (through its <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a>) a string of characters consisting \n    of either a forward slash (/) by itself or a string that must begin and end with forward slashes.\n    In addition, it can contain any ASCII character from the ! (<code>\\u0021</code>) through the DEL character (<code>\\u007F</code>), including \n    most punctuation characters, digits, and upper and lowercased letters.</p>\n         <note>\n            <p> If you are uploading a server certificate specifically for use with Amazon\n                CloudFront distributions, you must specify a path using the <code>path</code>\n                parameter. The path must begin with <code>/cloudfront</code> and must include a\n                trailing slash (for example, <code>/cloudfront/test/</code>).</p>\n         </note>"}))
    UploadServerCertificateRequest.add_member(:server_certificate_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerCertificateNameType, location_name: 'ServerCertificateName', traits: {"smithy.api#documentation" => "<p>The name for the server certificate. Do not include the path in this value. The name\n            of the certificate cannot contain any spaces.</p>\n         <p>This parameter allows (through its <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a>) a string of characters consisting of upper and lowercase alphanumeric \n    characters with no spaces. You can also include any of the following characters: _+=,.@-</p>", "smithy.api#required" => {}}))
    UploadServerCertificateRequest.add_member(:certificate_body, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateBodyType, location_name: 'CertificateBody', traits: {"smithy.api#documentation" => "<p>The contents of the public key certificate in PEM-encoded format.</p>\n         <p>The <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a> \n    used to validate this parameter is a string of characters consisting of the following:</p>\n         <ul>\n            <li>\n               <p>Any printable ASCII \n    character ranging from the space character (<code>\\u0020</code>) through the end of the ASCII character range</p>\n            </li>\n            <li>\n               <p>The printable characters in the Basic Latin and  Latin-1 Supplement character set \n    (through <code>\\u00FF</code>)</p>\n            </li>\n            <li>\n               <p>The special characters tab (<code>\\u0009</code>), line feed (<code>\\u000A</code>), and \n    carriage return (<code>\\u000D</code>)</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    UploadServerCertificateRequest.add_member(:private_key, Smithy::Schema::Shapes::ShapeRef.new(shape: PrivateKeyType, location_name: 'PrivateKey', traits: {"smithy.api#documentation" => "<p>The contents of the private key in PEM-encoded format.</p>\n         <p>The <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a> \n    used to validate this parameter is a string of characters consisting of the following:</p>\n         <ul>\n            <li>\n               <p>Any printable ASCII \n    character ranging from the space character (<code>\\u0020</code>) through the end of the ASCII character range</p>\n            </li>\n            <li>\n               <p>The printable characters in the Basic Latin and  Latin-1 Supplement character set \n    (through <code>\\u00FF</code>)</p>\n            </li>\n            <li>\n               <p>The special characters tab (<code>\\u0009</code>), line feed (<code>\\u000A</code>), and \n    carriage return (<code>\\u000D</code>)</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    UploadServerCertificateRequest.add_member(:certificate_chain, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateChainType, location_name: 'CertificateChain', traits: {"smithy.api#documentation" => "<p>The contents of the certificate chain. This is typically a concatenation of the\n            PEM-encoded public key certificates of the chain.</p>\n         <p>The <a href=\"http://wikipedia.org/wiki/regex\">regex pattern</a> \n    used to validate this parameter is a string of characters consisting of the following:</p>\n         <ul>\n            <li>\n               <p>Any printable ASCII \n    character ranging from the space character (<code>\\u0020</code>) through the end of the ASCII character range</p>\n            </li>\n            <li>\n               <p>The printable characters in the Basic Latin and  Latin-1 Supplement character set \n    (through <code>\\u00FF</code>)</p>\n            </li>\n            <li>\n               <p>The special characters tab (<code>\\u0009</code>), line feed (<code>\\u000A</code>), and \n    carriage return (<code>\\u000D</code>)</p>\n            </li>\n         </ul>"}))
    UploadServerCertificateRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagListType, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of tags that you want to attach to the new IAM server certificate resource.\n      Each tag consists of a key name and an associated value. For more information about tagging, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/id_tags.html\">Tagging IAM resources</a> in the\n      <i>IAM User Guide</i>.</p>\n         <note>\n            <p>If any one of the tags is invalid or if you exceed the allowed maximum number of tags, then the entire request \n   fails and the resource is not created.</p>\n         </note>"}))
